from pathlib import Path
import json,re,csv,hashlib,subprocess
R=Path(__file__).resolve().parents[1];O=R/'reports';O.mkdir(exist_ok=True)
def dumpcsv(path,rows):
 with path.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
chapters=[];equations=[];figs=[]
P=json.loads((R/'evidence/problem-bank-editorial.json').read_text())
C=json.loads((R/'evidence/case-bank-editorial.json').read_text())
E=json.loads((R/'evidence/exam-bank-editorial.json').read_text())
for n in range(1,26):
 path=R/'content'/f'c{n:02d}.tex';s=path.read_text().replace(fr'\input{{content/e{n:02d}.tex}}',(R/'content'/f'e{n:02d}.tex').read_text());title=re.search(r'\\chapter\{([^}]+)\}',s)[1]
 sections=re.findall(r'\\section\{([^}]+)\}',s);keys=re.findall(r'\\ilustra\{([^}]+)\}',s)
 chapters.append({'capitulo':n,'titulo':title,'bloque':'Materiales' if n<12 else 'Mantenimiento' if n<25 else 'Taller','desarrollo':'Completo en esta edición de estudio; revisión experta independiente pendiente','secciones':' | '.join(sections),'problemas':' '.join(p['key'] for p in P if p['ch']==n),'ejemplo_manual':f'M{n:02d}' if n<25 else 'Taller AULA-01','figuras':' '.join(keys),'pregunta_comprension':'Sí, con respuesta','palabras_aprox':len(s.split()),'archivo':f'content/c{n:02d}.tex + content/e{n:02d}.tex'})
 figs +=[{'key':key,'chapter':n} for key in keys]
 for j,m in enumerate(re.finditer(r'\\begin\{(equation\*?|align\*?)\}(.*?)\\end\{\1\}',s,re.S),1):
  eq=m[2];label=re.search(r'\\label\{([^}]+)\}',eq)
  equations.append({'id':label[1] if label else f'E{n:02d}-{j:02d}','capitulo':n,'latex':eq.strip(),'alcance':'Hipótesis y dominio en el capítulo; no todas las ecuaciones tienen prueba automática individual','verificacion':'Consultar math-checks.json y math-model-checks.json para controles ejecutados'})
for p in P:
 for i,eq in enumerate(p['eqs'],1):equations.append({'id':p['key']+f'-{i}','capitulo':p['ch'],'latex':eq,'alcance':p['hyp'],'verificacion':'Sustituciones registradas por clave del problema; adecuación física condicionada'})
dumpcsv(O/'Matriz_cobertura.csv',chapters);dumpcsv(O/'Inventario_ecuaciones.csv',equations)
(O/'coverage.json').write_text(json.dumps({'chapters':chapters,'equations':len(equations),'figures':figs,'problems':len(P),'cases':len(C),'exams':len(E),'exam_questions':sum(len(e['questions']) for e in E)},ensure_ascii=False,indent=2))
